import{_ as i,o,c as t,ag as l}from"./chunks/framework.B5ULsuav.js";const m=JSON.parse('{"title":"佛教学人入口","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-佛教学人.md","filePath":"30-学习路径/path-佛教学人.md","lastUpdated":1778155802000}'),e={name:"30-学习路径/path-佛教学人.md"};function r(d,a,h,s,u,n){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="佛教学人入口" tabindex="-1">佛教学人入口 <a class="header-anchor" href="#佛教学人入口" aria-label="Permalink to &quot;佛教学人入口&quot;">​</a></h1><blockquote><p>如果你学过净土、禅宗、或读过佛经，从这里开始了空居士的体系。</p></blockquote><hr><h2 id="你可能已经在修" tabindex="-1">你可能已经在修 <a class="header-anchor" href="#你可能已经在修" aria-label="Permalink to &quot;你可能已经在修&quot;">​</a></h2><ul><li><strong>净土念佛</strong> → 了空居士的念佛方法是&quot;心念耳闻+显现极乐&quot;，不是计数量。参见 <a href="/liaokongjushi-wisdom/20-专题研究/topic-入门实修">如何开始实修</a> 第二节</li><li><strong>禅宗参究</strong> → 了空居士说&quot;应无所住而生其心&quot;是总纲。不是坐着参，是在生活中历境炼心</li><li><strong>读经学教</strong> → 了空居士讲经&quot;直指人心&quot;——不讲学术考证，直接告诉你核心是什么、怎么用</li></ul><hr><h2 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h2><h3 id="第一步-先看心法" tabindex="-1">第一步：先看心法 <a class="header-anchor" href="#第一步-先看心法" aria-label="Permalink to &quot;第一步：先看心法&quot;">​</a></h3><p>了空居士把佛教修行的核心提炼为两个心法：</p><ol><li><p><strong>对境不住</strong>（不被现象迷惑）</p><ul><li>对应你熟悉的：&quot;应无所住而生其心&quot;&quot;凡所有相皆是虚妄&quot;</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住模型</a></li><li>原文入口：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></li></ul></li><li><p><strong>对法不执</strong>（连佛法也要放下）</p><ul><li>对应你熟悉的：&quot;法尚应舍，何况非法&quot;</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">对法不执模型</a></li><li>原文入口：<a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></li></ul></li></ol><h3 id="第二步-再看世界观" tabindex="-1">第二步：再看世界观 <a class="header-anchor" href="#第二步-再看世界观" aria-label="Permalink to &quot;第二步：再看世界观&quot;">​</a></h3><p>了解他如何用&quot;宇宙统一场&quot;翻译传统佛学概念：</p><ul><li>佛性 = 法性 = 实相 = 宇宙统一场</li><li>读：<a href="/liaokongjushi-wisdom/10-核心模型/model-天人合一">天人合一模型</a></li><li>原文入口：<a href="/liaokongjushi-wisdom/60-原文段落/论坛语录-宇宙统一场">论坛语录-宇宙统一场</a></li></ul><h3 id="第三步-方法和实践" tabindex="-1">第三步：方法和实践 <a class="header-anchor" href="#第三步-方法和实践" aria-label="Permalink to &quot;第三步：方法和实践&quot;">​</a></h3><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 抓核心，不搞繁复</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 中道，不走极端</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心</a> — 烦恼即菩提，生活即道场</li></ul><h3 id="第四步-功法-可选" tabindex="-1">第四步：功法（可选） <a class="header-anchor" href="#第四步-功法-可选" aria-label="Permalink to &quot;第四步：功法（可选）&quot;">​</a></h3><p>如果你对&quot;禅定&quot;的实操感兴趣：</p><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-性命双修">性命双修</a> — 他融合丹道的&quot;性命双修&quot;体系</li><li>读：<a href="/liaokongjushi-wisdom/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></li></ul><hr><h2 id="你可能发现的不同" tabindex="-1">你可能发现的不同 <a class="header-anchor" href="#你可能发现的不同" aria-label="Permalink to &quot;你可能发现的不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统佛教常见说法</th><th>了空居士的说法</th></tr></thead><tbody><tr><td>要断烦恼</td><td>烦恼即菩提——烦恼是觉悟的机会</td></tr><tr><td>要入定、不起念</td><td>不怕念起只怕觉迟——有念头正常，觉察到就是功夫</td></tr><tr><td>修行要远离尘世</td><td>家庭是道场，工作单位是道场</td></tr><tr><td>要持戒才能修行</td><td>不守五戒念佛也有用——因果分条算</td></tr><tr><td>要证果位</td><td>即得不等于得后——当下即是，不觉得证了什么才是真证得</td></tr></tbody></table><hr><h2 id="佛家概念词典" tabindex="-1">佛家概念词典 <a class="header-anchor" href="#佛家概念词典" aria-label="Permalink to &quot;佛家概念词典&quot;">​</a></h2><p>按传统对照，快速查阅：<a href="/liaokongjushi-wisdom/50-概念资料/50-概念资料_INDEX">概念词典</a></p><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-清净心">dict-清净心</a> / <a href="/liaokongjushi-wisdom/50-概念资料/dict-菩提">dict-菩提</a> / <a href="/liaokongjushi-wisdom/50-概念资料/dict-涅槃">dict-涅槃</a> — 佛家核心概念</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-我执">dict-我执</a> / <a href="/liaokongjushi-wisdom/50-概念资料/dict-法执">dict-法执</a> / <a href="/liaokongjushi-wisdom/50-概念资料/dict-无明">dict-无明</a> — 修行障碍</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-观照">dict-观照</a> / <a href="/liaokongjushi-wisdom/50-概念资料/dict-止观">dict-止观</a> — 修行方法</li></ul><h2 id="佛家金句" tabindex="-1">佛家金句 <a class="header-anchor" href="#佛家金句" aria-label="Permalink to &quot;佛家金句&quot;">​</a></h2><p><a href="/liaokongjushi-wisdom/40-原话金句/quote-佛家">佛家金句全集</a> — 金刚经、心经、公案经典原话</p><hr><blockquote><p>创建日期：2026-05-07</p></blockquote>',29)])])}const q=i(e,[["render",r]]);export{m as __pageData,q as default};
